type HerkulesPlan = { pools: { name: string; pool: string; total: number; remaining: number }[] }
function HerkulesPlanCard() {
  const role = useAuthStore((s) => s.auth.user?.role) ?? 0
  const [target, setTarget] = useState('')
  const [tier, setTier] = useState('lite')
  const [saving, setSaving] = useState(false)
  async function assign() {
    if (!/^[1-9][0-9]*$/.test(target)) { toast.error('Enter a valid user ID'); return }
    if (!window.confirm('Change plan? A different tier replaces this user’s weekly allowances.')) return
    setSaving(true)
    try {
      const res = await api.put(`/api/herkules/admin/users/${target}/plan`, { tier })
      if (!res.data.success) throw new Error('Assignment failed')
      toast.success('Plan assigned'); await query.refetch()
    } catch { toast.error('Could not assign plan') } finally { setSaving(false) }
  }
  const query = useQuery({ queryKey: ['herkules-plan'], queryFn: async () => {
    const res = await api.get('/api/herkules/plan')
    if (!res.data.success) throw new Error('Plan unavailable')
    return res.data.data as HerkulesPlan
  }, refetchInterval: 30000 })
  return <section className='mb-6 rounded-xl border p-5' aria-label='AI plan and allowances'>
    <h2 className='mb-2 text-lg font-semibold'>Your AI plan</h2>
    <p className='text-muted-foreground mb-4 text-sm'>Weekly allowances reset Monday at 00:00 Hong Kong time. Unused allowance expires. Local credits cannot pay for cloud models. Ask an administrator to change your plan.</p>
    {query.isPending && <p>Loading allowances…</p>}
    {query.isError && <p role='alert'>Allowances unavailable. Please retry shortly.</p>}
    <div className='grid gap-4 sm:grid-cols-2'>{query.data?.pools.map((p) => <div key={p.pool} className='rounded-lg bg-muted p-4'>
      <h3 className='font-medium'>{p.name.replace('Herkules ', '')}</h3>
      <p className='mt-2 text-xl'>{p.pool === 'cloud' ? `$${(p.remaining / 1000000).toFixed(2)}` : p.remaining.toLocaleString()} remaining</p>
      <p className='text-muted-foreground text-sm'>of {p.pool === 'cloud' ? `$${(p.total / 1000000).toFixed(2)} cloud allowance` : `${p.total.toLocaleString()} local credits`}</p>
    </div>)}</div>
    {role >= 10 && <div className='mt-5 flex flex-wrap items-end gap-3 border-t pt-4'>
      <label className='text-sm'>User ID<input className='ml-2 rounded border p-2' value={target} onChange={(e) => setTarget(e.target.value)} inputMode='numeric' /></label>
      <label className='text-sm'>Plan<select className='ml-2 rounded border p-2' value={tier} onChange={(e) => setTier(e.target.value)}><option value='lite'>Lite</option><option value='pro'>Pro</option><option value='max'>Max</option></select></label>
      <Button disabled={saving} onClick={() => void assign()}>Assign plan</Button>
    </div>}
  </section>
}

